const first = $input.first().json;
let raw = first.text ?? first.output ?? first.response ?? '';
let txt = String(raw).trim();
txt = txt.replace(/^```(?:json)?/i, '').replace(/```$/,'').trim();
const s = txt.indexOf('[');
const e = txt.lastIndexOf(']');
if (s !== -1 && e !== -1 && e > s) { txt = txt.slice(s, e + 1); }
let arr;
try { arr = JSON.parse(txt); } catch (err) { throw new Error('AI did not return valid JSON: ' + err.message + ' | got: ' + String(raw).slice(0, 300)); }
if (!Array.isArray(arr)) { arr = [arr]; }
return arr.map((tc) => ({ json: tc }));

